1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Scenario = {
18	  customer: { yearsWithMHPCO: number };
19	  steps: Step[];
20	};
21	
22	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
23	
24	const PROCESSING_FEE = 5;
25	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
26	
27	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
28	  sword: 100,
29	  amulet: 60,
30	  staff: 80,
31	  potion: 40,
32	  rune: 25,
33	  moonstone: 25,
34	};
35	
36	const basePremiumOf = (itemType: string): number =>
37	  BASE_PREMIUM_BY_ITEM_TYPE[itemType];
38	
39	const COMPONENT_BLOCK_SIZE = 3;
40	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
41	
42	const countByItemType = (items: Item[]): Map<string, number> => {
43	  const counts = new Map<string, number>();
44	  for (const item of items) {
45	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
46	  }
47	  return counts;
48	};
49	
50	const basePremiumForCountOf = (itemType: string, count: number): number =>
51	  count === COMPONENT_BLOCK_SIZE
52	    ? COMPONENT_BLOCK_BASE_PREMIUM
53	    : count * basePremiumOf(itemType);
54	
55	const policyBasePremiumOf = (items: Item[]): number => {
56	  let total = 0;
57	  for (const [itemType, count] of countByItemType(items)) {
58	    total += basePremiumForCountOf(itemType, count);
59	  }
60	  return total;
61	};
62	
63	const quotePremium = (items: Item[]): number => {
64	  const policyBasePremium = policyBasePremiumOf(items);
65	  const firstInsuranceSurcharge =
66	    (policyBasePremium * FIRST_INSURANCE_SURCHARGE_PERCENT) / 100;
67	
68	  return Math.ceil(
69	    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
70	  );
71	};
72	
73	export const runScenario = (scenario: Scenario): StepResult[] =>
74	  scenario.steps.map((step) => {
75	    if (step.op === "quote") return { premium: quotePremium(step.items) };
76	    throw new Error(`Unsupported step: ${step.op}`);
77	  });
